const{kv:kv}=require("@vercel/kv"),MAX_VALUE_BYTES=2097152;function isValidCode(t){return"string"==typeof t&&/^[a-z0-9-]{1,64}$/.test(t)}function isValidKey(t){return"string"==typeof t&&/^[a-zA-Z0-9_-]{1,64}$/.test(t)}module.exports=async function(t,e){e.setHeader("Cache-Control","no-store");const{code:o,key:r}=t.query;if(!isValidCode(o)||!isValidKey(r))return void e.status(400).json({error:"Invalid or missing code/key"});const s=`household:${o}:${r}`,a=`household:${o}:__meta`;try{if("GET"===t.method){const t=await kv.get(s);return void e.status(200).json({value:void 0===t?null:t})}if("POST"===t.method){let o=t.body;if("string"==typeof o)try{o=JSON.parse(o)}catch(t){o={}}const n=o&&o.value;if("string"!=typeof n)return void e.status(400).json({error:"value must be a JSON string"});if(n.length>2097152)return void e.status(413).json({error:"value too large"});await kv.set(s,n);const i=Date.now();return await kv.set(a,JSON.stringify({updatedAt:i,changedKey:r})),void e.status(200).json({ok:!0,updatedAt:i})}if("DELETE"===t.method){await kv.del(s);const t=Date.now();return await kv.set(a,JSON.stringify({updatedAt:t,changedKey:r})),void e.status(200).json({ok:!0,updatedAt:t})}e.setHeader("Allow",["GET","POST","DELETE"]),e.status(405).json({error:`Method ${t.method} not allowed`})}catch(t){console.error("household api error",t),e.status(500).json({error:"Storage backend error — is a KV database connected to this Vercel project?"})}};